// Load Supabase dynamically so a CDN/network failure does not prevent the auth UI
// from initializing; otherwise every button appears dead when the module import fails.
let createClient = null;
let supabaseLoadError = null;
try {
  ({ createClient } = await import('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm'));
} catch (error) {
  supabaseLoadError = error;
  console.error('[AELTRIX] Could not load the Supabase client library.', error);
}

// Configure in config.js (copy config.example.js). Supabase anon key is intended for browser use; protect data with RLS.
// Load config defensively: a missing/misnamed config.js should not disable all UI buttons.
let SUPABASE_URL = '';
let SUPABASE_ANON_KEY = '';
try {
  const appConfig = await import('./config.js');
  SUPABASE_URL = appConfig.SUPABASE_URL || '';
  SUPABASE_ANON_KEY = appConfig.SUPABASE_ANON_KEY || '';
} catch (configError) {
  console.error('[AELTRIX] Could not load config.js. Check the filename and exports.', configError);
}
const $ = (id) => document.getElementById(id);
const authView=$('authView'), appView=$('appView'), authForm=$('authForm'), authMessage=$('authMessage');
let supabase=null, user=null, myProfile=null, mode='login', presenceChannel=null, inviteChannel=null, peer=null, peerConnections=new Map(), chats=new Map(), activeChatId=null, incomingInvites=new Map(), outgoingInvites=new Map(), acceptedInvites=new Map(), onlineUsers=new Map(), searchTimer=null, pendingModalInvite=null, toastTimer=null, replyDraft=null, incomingTransfers=new Map(), outgoingTransfers=new Map(), identityPrivateKey=null, identityPublicJwk=null, signingPrivateKey=null, signingPublicJwk=null, persistentKeys=new Map(), sessionGeneration=0;
const encoder=new TextEncoder(), decoder=new TextDecoder();
const sections={feed:$('feedSection'),people:$('peopleSection'),messages:$('messagesSection'),profile:$('profileSection')};
const sectionNames={feed:'الرئيسية',people:'اكتشف الناس',messages:'الرسائل',profile:'ملفي الشخصي'};

function toast(msg,error=false){const t=$('toast');t.textContent=msg;t.classList.toggle('error',error);t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3400)}
function authMsg(msg,error=false){authMessage.textContent=msg;authMessage.classList.toggle('error',error)}
function applyTheme(theme){const dark=theme==='dark';document.documentElement.dataset.theme=dark?'dark':'light';const b=$('themeToggle');if(b){b.textContent=dark?'☀️':'🌙';b.title=dark?'تفعيل الوضع الفاتح':'تفعيل الوضع الداكن';b.setAttribute('aria-label',b.title)}const meta=document.querySelector('meta[name=theme-color]');if(meta)meta.content=dark?'#11121a':'#f6f7fb'}
applyTheme(localStorage.getItem('aeltrix-theme')||'light');
$('themeToggle')?.addEventListener('click',()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';localStorage.setItem('aeltrix-theme',next);applyTheme(next)});
function setBusy(b){$('authSubmit').disabled=b;$('authSubmit').innerHTML=b?'لحظة…':'<span>↗</span> '+(mode==='login'?'دخول':'إنشاء الحساب')}
function initials(name){return (name||'A').trim().slice(0,1).toUpperCase()||'A'}
function escapeHtml(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function showMode(next){mode=next;const signup=mode==='signup';$('loginTab').classList.toggle('active',!signup);$('signupTab').classList.toggle('active',signup);$('usernameWrap').classList.toggle('hidden',!signup);$('username').required=signup;$('usernameLabel').classList.toggle('hidden',!signup);$('authTitle').textContent=signup?'ابدأ مساحتك الخاصة.':'مساحتك، بطريقتك.';$('authSubtitle').textContent=signup?'أنشئ هويتك وابدأ التواصل مع أصحابك.':'تواصل مع أصحابك في مساحة صُممت لكم.';$('authSubmit').textContent=signup?'إنشاء الحساب ↗':'دخول ↗';$('password').autocomplete=signup?'new-password':'current-password';authMsg('')}
$('loginTab').onclick=()=>showMode('login');$('signupTab').onclick=()=>showMode('signup');$('togglePassword').onclick=()=>{$('password').type=$('password').type==='password'?'text':'password'};

function configReady(){return SUPABASE_URL&&SUPABASE_ANON_KEY&&!SUPABASE_URL.includes('YOUR_')&&!SUPABASE_ANON_KEY.includes('YOUR_')}
function initSupabase(){if(typeof createClient!=='function'){authMsg('تعذر تحميل مكتبة Supabase. تأكد من الإنترنت أو جرّب فتح الموقع لاحقًا. إذا استمرت المشكلة، افحص اتصال CDN.',true);return false}if(!configReady()){authMsg('إعداد Supabase ناقص: تأكد من وجود config.js بجانب index.html وأن الرابط والمفتاح العام صحيحان.',true);return false}try{supabase=createClient(SUPABASE_URL,SUPABASE_ANON_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});return true}catch(error){console.error('[AELTRIX] Supabase initialization failed.',error);authMsg('تعذر تهيئة Supabase. تحقق من رابط المشروع والمفتاح العام في config.js.',true);return false}}

authForm.addEventListener('submit',async e=>{e.preventDefault();if(!supabase&&!initSupabase())return;setBusy(true);authMsg('');const email=$('email').value.trim(),password=$('password').value,username=$('username').value.trim().toLowerCase();try{if(mode==='signup'){if(!/^[a-z0-9_]{3,24}$/.test(username))throw new Error('اسم المستخدم يجب أن يكون 3–24 حرفًا إنجليزيًا صغيرًا أو رقمًا أو _.');const {data,error}=await supabase.auth.signUp({email,password,options:{data:{username,display_name:username}}});if(error)throw error;if(data.session){user=data.user;await enterApp()}else authMsg('تم إنشاء الحساب. افحص بريدك لتأكيده، ثم سجّل الدخول. سيُنشأ ملفك الشخصي عند أول دخول.')}else{const {data,error}=await supabase.auth.signInWithPassword({email,password});if(error)throw error;user=data.user;await enterApp()}}catch(err){authMsg(friendlyError(err),true)}finally{setBusy(false)}});
function friendlyError(e){let m=e?.message||'حدث خطأ غير متوقع.';if(/Invalid login credentials/i.test(m))return 'البريد أو كلمة المرور غير صحيحة.';if(/already registered/i.test(m))return 'هذا البريد مسجل بالفعل.';if(/duplicate key|profiles_username_key/i.test(m))return 'اسم المستخدم مستخدم بالفعل، اختر اسمًا آخر.';return m}

async function enterApp(){if(!supabase&&!initSupabase())return;const generation=++sessionGeneration;const {data:{user:u}}=await supabase.auth.getUser();if(generation!==sessionGeneration)return;if(!u){authView.classList.remove('hidden');appView.classList.add('hidden');return}user=u;let {data:profile,error}=await supabase.from('profiles').select('*').eq('id',user.id).maybeSingle();if(generation!==sessionGeneration)return;if(error)throw error;if(!profile){let proposed=(user.user_metadata?.username||user.email?.split('@')[0]||'aeltrix').toLowerCase().replace(/[^a-z0-9_]/g,'').slice(0,24)||'aeltrix';if(proposed.length<3)proposed=('user_'+user.id.slice(0,8)).slice(0,24);let created=await supabase.from('profiles').insert({id:user.id,username:proposed,display_name:user.user_metadata?.display_name||proposed,bio:''}).select().single();if(created.error?.code==='23505'){const replacement=prompt('اسم المستخدم مستخدم بالفعل. اختر اسمًا آخر (3–24 حرفًا صغيرًا أو رقمًا أو _):');if(!replacement)throw new Error('أكمل إعداد ملفك الشخصي عند تسجيل الدخول مجددًا.');proposed=replacement.trim().toLowerCase();if(!/^[a-z0-9_]{3,24}$/.test(proposed))throw new Error('اسم المستخدم يجب أن يكون 3–24 حرفًا صغيرًا أو رقمًا أو _.');created=await supabase.from('profiles').insert({id:user.id,username:proposed,display_name:user.user_metadata?.display_name||proposed,bio:''}).select().single()}if(created.error)throw created.error;profile=created.data}if(generation!==sessionGeneration)return;myProfile=profile;await ensureIdentityKeyAndPublish();if(generation!==sessionGeneration)return;authView.classList.add('hidden');appView.classList.remove('hidden');renderMyProfile();if(!peer)initPeer();if(!presenceChannel)await initPresence();if(generation!==sessionGeneration)return;if(!inviteChannel)await initInviteChannel();if(generation!==sessionGeneration)return;await loadSavedConversations();if(generation!==sessionGeneration)return;showSection('feed');loadOnlinePreview()}
function renderMyProfile(){$('welcomeName').textContent=myProfile.display_name||myProfile.username;$('headerAvatar').textContent=initials(myProfile.display_name||myProfile.username);$('profileAvatar').textContent=initials(myProfile.display_name||myProfile.username);$('profileName').textContent='@'+myProfile.username;$('profileEmail').textContent=user.email||'';$('displayName').value=myProfile.display_name||'';$('bioInput').value=myProfile.bio||''}
$('profileForm').addEventListener('submit',async e=>{e.preventDefault();const ownerId=user?.id,generation=sessionGeneration;if(!ownerId)return;const display_name=$('displayName').value.trim().slice(0,40),bio=$('bioInput').value.trim().slice(0,160);const {data,error}=await supabase.from('profiles').update({display_name,bio}).eq('id',ownerId).select().single();if(generation!==sessionGeneration||ownerId!==user?.id)return;if(error){toast(friendlyError(error),true);return}myProfile=data;renderMyProfile();toast('تم حفظ ملفك الشخصي.')});
$('logoutBtn').onclick=async()=>{if(!supabase)return;sessionGeneration++;cleanup();user=null;myProfile=null;authView.classList.remove('hidden');appView.classList.add('hidden');const {error}=await supabase.auth.signOut();if(error)authMsg('تعذر إنهاء الجلسة على الخادم. أعد المحاولة.',true)};$('headerAvatar').onclick=()=>showSection('profile');

function showSection(name){Object.entries(sections).forEach(([k,v])=>v.classList.toggle('hidden',k!==name));document.querySelectorAll('[data-section]').forEach(b=>b.classList.toggle('selected',b.dataset.section===name));$('sectionTitle').textContent=sectionNames[name]||'AELTRIX';if(name==='people')searchPeople($('peopleSearch').value.trim());if(name==='messages')renderInvites();if(name==='feed')loadOnlinePreview()}
document.querySelectorAll('[data-section]').forEach(b=>b.addEventListener('click',()=>showSection(b.dataset.section)));document.querySelectorAll('[data-goto]').forEach(b=>b.addEventListener('click',()=>showSection(b.dataset.goto)));

// Presence: one Supabase Realtime Presence channel. It carries profile IDs and public display names only.
async function initPresence(){presenceChannel=supabase.channel('aeltrix:online:v1',{config:{presence:{key:user.id}}});presenceChannel.on('presence',{event:'sync'},syncOnline).on('presence',{event:'join'},syncOnline).on('presence',{event:'leave'},syncOnline);const status=await presenceChannel.subscribe(async s=>{if(s==='SUBSCRIBED'){await presenceChannel.track({user_id:user.id,username:myProfile.username,display_name:myProfile.display_name||myProfile.username,peer_id:peer?.id||null,at:new Date().toISOString()})}});if(status==='CHANNEL_ERROR')toast('تعذر الاتصال بخدمة الحضور. تحقق من إعدادات Realtime.',true)}
function syncOnline(){onlineUsers.clear();const state=presenceChannel?.presenceState()||{};for(const [key,metas] of Object.entries(state)){const meta=metas?.[metas.length-1],id=meta?.user_id;if(typeof id!=='string'||id===user?.id||!/^[0-9a-f-]{36}$/i.test(id)||typeof meta.username!=='string'||!/^[a-z0-9_]{3,24}$/.test(meta.username)||typeof meta.peer_id!=='string'||meta.peer_id.length>256)continue;onlineUsers.set(id,{...meta,display_name:typeof meta.display_name==='string'?meta.display_name.slice(0,40):meta.username})}$('onlineCount').textContent=onlineUsers.size;renderPeopleFromOnline();loadOnlinePreview()}
async function updatePresencePeer(){if(presenceChannel&&peer?.id)await presenceChannel.track({user_id:user.id,username:myProfile.username,display_name:myProfile.display_name||myProfile.username,peer_id:peer.id,at:new Date().toISOString()})}

// PeerJS handles signaling. WebRTC DataChannels use DTLS; this prototype also wraps text in AES-GCM with an ECDH-derived key.
function initPeer(){try{peer=new Peer(undefined,{debug:0,config:{iceServers:[{urls:'stun:stun.l.google.com:19302'},{urls:'stun:stun.cloudflare.com:3478'}],iceCandidatePoolSize:4}});peer.on('open',async id=>{await updatePresencePeer();console.info('[AELTRIX] peer ready',id)});peer.on('connection',conn=>wireConnection(conn,false));peer.on('error',err=>{console.warn('[AELTRIX] PeerJS',err);if(['peer-unavailable','network','server-error'].includes(err.type))toast('تعذر الوصول إلى الصديق. تأكد أنه متصل ثم أعد الدعوة.',true)});peer.on('disconnected',()=>{console.warn('[AELTRIX] Peer signaling disconnected')})}catch(e){console.error(e);toast('تعذر تهيئة الاتصال المباشر.',true)}}
async function initInviteChannel(){inviteChannel=supabase.channel('aeltrix:invites:'+user.id,{config:{broadcast:{self:false}}});inviteChannel.on('broadcast',{event:'invite'},({payload})=>receiveInvite(payload)).on('broadcast',{event:'invite-response'},({payload})=>handleInviteResponse(payload)).subscribe(s=>{if(s==='SUBSCRIBED')console.info('[AELTRIX] invite channel ready')})}
async function sendInvite(person){if(!peer?.id){toast('الاتصال لم يجهز بعد، انتظر لحظة.',true);return}if(!person?.id||person.id===user?.id||!person.peer_id){toast('معرّف الاتصال غير صالح أو غير جاهز عند هذا المستخدم.',true);return}const inviteId=crypto.randomUUID(),target=supabase.channel('aeltrix:invites:'+person.id,{config:{broadcast:{self:false}}});outgoingInvites.set(inviteId,{targetId:person.id,peerId:person.peer_id,expiresAt:Date.now()+120000});await target.subscribe(async state=>{if(state==='SUBSCRIBED'){await target.send({type:'broadcast',event:'invite',payload:{protocol:2,invite_id:inviteId,from_id:user.id,to_id:person.id,from_username:myProfile.username,from_name:myProfile.display_name||myProfile.username,from_peer:peer.id,at:Date.now()}});toast('تم إرسال الدعوة إلى @'+person.username);setTimeout(()=>supabase.removeChannel(target),1800)}})}
function receiveInvite(payload){if(!payload||payload.protocol!==2||!payload.invite_id||payload.from_id===user?.id||payload.to_id!==user?.id||!payload.from_peer||!Number.isFinite(payload.at)||Date.now()-payload.at>120000)return;incomingInvites.set(payload.invite_id,payload);renderInvites();pendingModalInvite=payload;$('inviteModalTitle').textContent='@'+(payload.from_name||payload.from_username)+' يدعوك';$('inviteModalText').textContent='هل تريد قبول دعوة محادثة خاصة؟ لن يبدأ الاتصال إلا بعد موافقتك.';$('inviteModal').classList.remove('hidden');$('inviteBadge').classList.remove('hidden');$('inviteBadge').textContent=incomingInvites.size;$('pendingCount').textContent=incomingInvites.size}
async function replyInvite(inv,accepted){if(!inv||inv.to_id!==user?.id||!inv.invite_id)return;if(accepted)acceptedInvites.set(inv.invite_id,{remoteId:inv.from_id,expiresAt:Date.now()+120000});const ch=supabase.channel('aeltrix:invites:'+inv.from_id,{config:{broadcast:{self:false}}});await ch.subscribe(async state=>{if(state==='SUBSCRIBED'){await ch.send({type:'broadcast',event:'invite-response',payload:{protocol:2,invite_id:inv.invite_id,from_id:user.id,to_id:inv.from_id,from_username:myProfile.username,from_name:myProfile.display_name||myProfile.username,accepted,peer_id:peer?.id||null}});setTimeout(()=>supabase.removeChannel(ch),1500)}});incomingInvites.delete(inv.invite_id);$('inviteModal').classList.add('hidden');renderInvites();if(accepted){showSection('messages');toast('وافقت على الدعوة. جارٍ الاتصال…')}}
$('acceptInvite').onclick=()=>replyInvite(pendingModalInvite,true);$('declineInvite').onclick=()=>replyInvite(pendingModalInvite,false);document.querySelectorAll('[data-close-modal]').forEach(x=>x.onclick=()=>{$('inviteModal').classList.add('hidden')});
function handleInviteResponse(p){if(!p||p.protocol!==2||p.to_id!==user?.id||!p.invite_id)return;const pending=outgoingInvites.get(p.invite_id);if(!pending||pending.expiresAt<Date.now()||pending.targetId!==p.from_id){outgoingInvites.delete(p.invite_id);return}outgoingInvites.delete(p.invite_id);if(!p.accepted){toast('@'+p.from_username+' رفض الدعوة.');return}if(!p.peer_id||p.from_id===user.id){toast('استجابة الدعوة غير صالحة.',true);return}const metadata={protocol:2,inviteId:p.invite_id,initiatorUserId:user.id,recipientUserId:p.from_id,initiatorName:myProfile.display_name||myProfile.username,recipientName:p.from_name||p.from_username};const conn=peer.connect(p.peer_id,{reliable:true,serialization:'json',metadata});wireConnection(conn,true);showSection('messages');toast('قبل صديقك الدعوة، جارٍ إنشاء الاتصال…')}

function clearTransfersForConnection(conn){for(const [id,t] of incomingTransfers){if(t.conn===conn){clearTimeout(t.timer);incomingTransfers.delete(id)}}for(const [id,t] of outgoingTransfers){if(t.conn===conn){clearTimeout(t.timer);outgoingTransfers.delete(id);t.reject?.(new Error('انقطع الاتصال أثناء نقل الصورة'))}}}
const jwkFingerprint=async jwk=>bytesToB64(new Uint8Array(await crypto.subtle.digest('SHA-256',encoder.encode(JSON.stringify({kty:jwk.kty,crv:jwk.crv,x:jwk.x,y:jwk.y})))));
async function trustedSigningKey(peerId){const {data,error}=await supabase.from('profiles').select('signing_public_key').eq('id',peerId).maybeSingle();if(error)throw error;const jwk=data?.signing_public_key;if(!jwk)throw new Error('هذا المستخدم لم يفعّل المصادقة المشفرة v1.6 بعد');const keyId=`trust:${user.id}:${peerId}`,db=await openIdentityDb();const saved=await new Promise((resolve,reject)=>{const tx=db.transaction('identity','readonly'),r=tx.objectStore('identity').get(keyId);r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>reject(r.error)});db.close();const encoded=JSON.stringify({kty:jwk.kty,crv:jwk.crv,x:jwk.x,y:jwk.y});const fp=await jwkFingerprint(jwk);if(saved&&saved.encoded!==encoded&&!confirm(`تحذير: تغير مفتاح هوية الصديق. البصمة الجديدة: ${fp}\\nلا توافق إلا بعد التحقق من التغيير ومقارنة البصمة عبر قناة مستقلة. هل تريد استبدال المفتاح المحفوظ؟`))throw new Error('تم رفض تغيير مفتاح هوية الصديق');if(!saved||saved.encoded!==encoded){if(!saved&&!confirm(`مفتاح توقيع جديد لهذا الصديق. بصمة SHA-256: ${fp}\\nلا تعتبر الهوية مؤكدة إلا بعد مقارنة البصمة عبر قناة مستقلة. الوثوق الآن يفعّل TOFU لهذا الجهاز فقط. هل تريد المتابعة؟`))throw new Error('لم يتم الوثوق بمفتاح الصديق');const db2=await openIdentityDb();await new Promise((resolve,reject)=>{const tx=db2.transaction('identity','readwrite');tx.objectStore('identity').put({encoded,fingerprint:fp},keyId);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db2.close()}return crypto.subtle.importKey('jwk',jwk,{name:'ECDSA',namedCurve:'P-256'},false,['verify'])}
async function verifySignedHello(conn,data,remoteId,meta){if(data.fromId!==remoteId||data.toId!==user.id||data.inviteId!==meta.inviteId||!data.nonce||!Number.isFinite(data.at)||Math.abs(Date.now()-data.at)>120000)throw new Error('بيانات المصافحة غير صالحة أو قديمة');conn._aeltrixSeenNonces??=new Set();if(conn._aeltrixSeenNonces.has(data.nonce))throw new Error('تم رفض مصافحة مكررة');const key=await trustedSigningKey(remoteId),body=encoder.encode(JSON.stringify({protocol:2,fromId:data.fromId,toId:data.toId,inviteId:data.inviteId,key:data.key,nonce:data.nonce,at:data.at}));if(!await crypto.subtle.verify({name:'ECDSA',hash:'SHA-256'},key,b64ToBytes(data.signature),body))throw new Error('فشل التحقق من توقيع هوية الصديق');conn._aeltrixSeenNonces.add(data.nonce);conn._aeltrixKey=await deriveCryptoKey(conn,data.key);if(!conn._aeltrixReady){conn._aeltrixReady=true;updateChatStatus(remoteId,true)}}
async function makeSignedHello(conn,meta,remoteId){const key=await crypto.subtle.exportKey('jwk',conn._aeltrixKeyPair.publicKey),payload={protocol:2,fromId:user.id,toId:remoteId,inviteId:meta.inviteId,key,nonce:crypto.randomUUID(),at:Date.now()},body=encoder.encode(JSON.stringify(payload)),signature=await crypto.subtle.sign({name:'ECDSA',hash:'SHA-256'},signingPrivateKey,body);return {kind:'hello',...payload,signature:bytesToB64(new Uint8Array(signature))}}
async function deriveCryptoKey(conn,publicKey){const remote=await crypto.subtle.importKey('jwk',publicKey,{name:'ECDH',namedCurve:'P-256'},false,[]);const shared=await crypto.subtle.deriveBits({name:'ECDH',public:remote},conn._aeltrixKeyPair.privateKey,256);const material=await crypto.subtle.importKey('raw',shared,'HKDF',false,['deriveKey']);return crypto.subtle.deriveKey({name:'HKDF',hash:'SHA-256',salt:encoder.encode('AELTRIX-chat-v1'),info:encoder.encode('chat-payload-v2')},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
const bytesToB64=a=>{let out='';for(let i=0;i<a.length;i+=0x8000)out+=String.fromCharCode(...a.subarray(i,i+0x8000));return btoa(out)};
const b64ToBytes=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
async function encryptPacket(key,bytes){const iv=crypto.getRandomValues(new Uint8Array(12));const cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,bytes);return {iv:bytesToB64(iv),cipher:bytesToB64(new Uint8Array(cipher))}}
async function decryptPacket(key,packet){return new Uint8Array(await crypto.subtle.decrypt({name:'AES-GCM',iv:b64ToBytes(packet.iv)},key,b64ToBytes(packet.cipher)))}
function openIdentityDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open('aeltrix-secure-identity',1);req.onupgradeneeded=()=>req.result.createObjectStore('identity');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function readIdentity(){const db=await openIdentityDb();return new Promise((resolve,reject)=>{const tx=db.transaction('identity','readonly'),req=tx.objectStore('identity').get(user.id);req.onsuccess=()=>{db.close();resolve(req.result||null)};req.onerror=()=>{db.close();reject(req.error)}})}
async function saveIdentity(value){const db=await openIdentityDb();return new Promise((resolve,reject)=>{const tx=db.transaction('identity','readwrite');tx.objectStore('identity').put(value,user.id);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)}})}
async function ensureIdentityKeyAndPublish(){let saved=await readIdentity();if(!saved){const pair=await crypto.subtle.generateKey({name:'ECDH',namedCurve:'P-256'},true,['deriveBits']);const privateJwk=await crypto.subtle.exportKey('jwk',pair.privateKey),publicJwk=await crypto.subtle.exportKey('jwk',pair.publicKey),privateKey=await crypto.subtle.importKey('jwk',privateJwk,{name:'ECDH',namedCurve:'P-256'},false,['deriveBits']);saved={privateKey,publicJwk};await saveIdentity(saved)}if(!saved.signingPrivateKey||!saved.signingPublicJwk){const pair=await crypto.subtle.generateKey({name:'ECDSA',namedCurve:'P-256'},true,['sign','verify']),privateJwk=await crypto.subtle.exportKey('jwk',pair.privateKey);saved.signingPublicJwk=await crypto.subtle.exportKey('jwk',pair.publicKey);saved.signingPrivateKey=await crypto.subtle.importKey('jwk',privateJwk,{name:'ECDSA',namedCurve:'P-256'},false,['sign']);await saveIdentity(saved)}identityPrivateKey=saved.privateKey;identityPublicJwk=saved.publicJwk;signingPrivateKey=saved.signingPrivateKey;signingPublicJwk=saved.signingPublicJwk;const {error}=await supabase.from('profiles').update({e2ee_public_key:identityPublicJwk,signing_public_key:signingPublicJwk}).eq('id',user.id);if(error)throw new Error('تعذر نشر مفاتيح التشفير والتوقيع. شغّل تحديث قاعدة البيانات من supabase-schema.sql ثم أعد تحميل الموقع. التفاصيل: '+error.message)}
async function persistentChatKey(peerId){if(persistentKeys.has(peerId))return persistentKeys.get(peerId);if(!identityPrivateKey)throw new Error('مفتاح التشفير المحلي غير جاهز');const {data,error}=await supabase.from('profiles').select('e2ee_public_key').eq('id',peerId).maybeSingle();if(error)throw error;if(!data?.e2ee_public_key)throw new Error('هذا المستخدم لم يفعّل مفاتيح التشفير بعد. يجب أن يفتح الموقع المحدّث مرة واحدة.');const remote=await crypto.subtle.importKey('jwk',data.e2ee_public_key,{name:'ECDH',namedCurve:'P-256'},false,[]);const shared=await crypto.subtle.deriveBits({name:'ECDH',public:remote},identityPrivateKey,256);const material=await crypto.subtle.importKey('raw',shared,'HKDF',false,['deriveKey']);const ids=[user.id,peerId].sort().join(':');const key=await crypto.subtle.deriveKey({name:'HKDF',hash:'SHA-256',salt:encoder.encode('AELTRIX-local-chat-v2'),info:encoder.encode(ids)},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt']);persistentKeys.set(peerId,key);return key}
function openLocalDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open('aeltrix-local-v2',1);req.onupgradeneeded=()=>{const db=req.result;if(!db.objectStoreNames.contains('messages'))db.createObjectStore('messages',{keyPath:'key'});if(!db.objectStoreNames.contains('contacts'))db.createObjectStore('contacts',{keyPath:'key'});if(!db.objectStoreNames.contains('media'))db.createObjectStore('media',{keyPath:'key'});if(!db.objectStoreNames.contains('stickers'))db.createObjectStore('stickers',{keyPath:'key'})};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function localStore(storeName,mode,action){const db=await openLocalDb();return new Promise((resolve,reject)=>{const tx=db.transaction(storeName,mode),store=tx.objectStore(storeName);let result;try{result=action(store)}catch(e){db.close();reject(e);return}tx.oncomplete=()=>{db.close();resolve(result?.result)};tx.onerror=()=>{const e=tx.error;db.close();reject(e)};tx.onabort=()=>{const e=tx.error;db.close();reject(e||new Error('Local database transaction aborted'))}})}
async function localGetAll(storeName){const db=await openLocalDb();return new Promise((resolve,reject)=>{const tx=db.transaction(storeName,'readonly'),req=tx.objectStore(storeName).getAll();req.onsuccess=()=>{const out=req.result||[];db.close();resolve(out)};req.onerror=()=>{db.close();reject(req.error)}})}
async function localGet(storeName,key){const db=await openLocalDb();return new Promise((resolve,reject)=>{const tx=db.transaction(storeName,'readonly'),req=tx.objectStore(storeName).get(key);req.onsuccess=()=>{const out=req.result||null;db.close();resolve(out)};req.onerror=()=>{db.close();reject(req.error)}})}
const localKey=(peerId,messageId)=>`${user.id}:${peerId}:${messageId}`;
async function saveLocalContact(peerId,name){const record={key:`${user.id}:${peerId}`,ownerId:user.id,peerId,name:name||'محادثة'};await localStore('contacts','readwrite',store=>store.put(record))}
async function persistPayload(peerId,payload,messageId,at,mine=true){const ownerId=user?.id,generation=sessionGeneration;if(!ownerId)throw new Error('لا توجد جلسة مستخدم نشطة');const key=await persistentChatKey(peerId);if(generation!==sessionGeneration||ownerId!==user?.id)throw new Error('تغيرت الجلسة أثناء حفظ الرسالة');const packet=await encryptPacket(key,encoder.encode(JSON.stringify(payload))),recordKey=`${ownerId}:${peerId}:${messageId}`;await localStore('messages','readwrite',store=>store.put({key:recordKey,ownerId,peerId,messageId,mine,at,iv:packet.iv,ciphertext:packet.cipher}));if(generation!==sessionGeneration||ownerId!==user?.id)throw new Error('تغيرت الجلسة أثناء حفظ الرسالة');const c=chats.get(peerId);await saveLocalContact(peerId,c?.name||'محادثة');return packet}
async function persistEncryptedImage(c,file,messageId,at,mine=true){const ownerId=user?.id,generation=sessionGeneration;if(!ownerId)throw new Error('لا توجد جلسة مستخدم نشطة');const key=await persistentChatKey(c.id),raw=new Uint8Array(await file.arrayBuffer());if(generation!==sessionGeneration||ownerId!==user?.id)throw new Error('تغيرت الجلسة أثناء حفظ الصورة');const iv=crypto.getRandomValues(new Uint8Array(12)),encrypted=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv},key,raw)),combined=new Uint8Array(iv.length+encrypted.length);combined.set(iv,0);combined.set(encrypted,iv.length);const mediaKey=`${ownerId}:${c.id}:${messageId}`;await localStore('media','readwrite',store=>store.put({key:mediaKey,ownerId,peerId:c.id,messageId,bytes:combined.buffer,mime:file.type||'image/png'}));if(generation!==sessionGeneration||ownerId!==user?.id)throw new Error('تغيرت الجلسة أثناء حفظ الصورة');const payload={type:'image',name:file.name||'image',size:file.size,mime:file.type||'image/*',localMediaKey:mediaKey};await persistPayload(c.id,payload,messageId,at,mine);return payload}
async function loadStoredImage(peerId,payload,messageId){const mediaKey=payload.localMediaKey||localKey(peerId,messageId);const row=await localGet('media',mediaKey);if(row?.ownerId!==user.id)throw new Error('الصورة غير موجودة في التخزين المحلي');if(!row)throw new Error('الصورة غير موجودة في التخزين المحلي');const bytes=new Uint8Array(row.bytes);if(bytes.length<29)throw new Error('ملف صورة مشفّر غير صالح');const key=await persistentChatKey(peerId);const iv=bytes.slice(0,12),cipher=bytes.slice(12);const clear=await crypto.subtle.decrypt({name:'AES-GCM',iv},key,cipher);const blob=new Blob([clear],{type:payload.mime||row.mime||'image/*'});return {type:'image',url:URL.createObjectURL(blob),name:payload.name||'صورة',size:payload.size||blob.size}}
async function loadSavedConversations(){const generation=sessionGeneration,ownerId=user?.id;if(!ownerId)return;try{const rows=(await localGetAll('contacts')).filter(x=>x.ownerId===ownerId);if(generation!==sessionGeneration||ownerId!==user?.id)return;for(const row of rows)createChatRecord(row.peerId,row.name,null);if(rows.length)toast('تم تحميل محادثات هذا الجهاز من التخزين المحلي.');else renderChatList()}catch(e){if(generation===sessionGeneration)console.warn('[AELTRIX] Local conversations unavailable',e);if(generation===sessionGeneration)toast('تعذر فتح التخزين المحلي للمحادثات.',true)}}
async function loadChatHistory(c){const generation=sessionGeneration,ownerId=user?.id;if(!ownerId)return;try{const rows=(await localGetAll('messages')).filter(r=>r.ownerId===ownerId&&r.peerId===c.id).sort((a,b)=>a.at-b.at).slice(-500);if(generation!==sessionGeneration||ownerId!==user?.id)return;for(const row of rows){if(generation!==sessionGeneration||ownerId!==user?.id)return;if(c.messages.some(m=>m.id===row.messageId))continue;try{const key=await persistentChatKey(c.id);if(generation!==sessionGeneration||ownerId!==user?.id)return;const raw=await decryptPacket(key,{iv:row.iv,cipher:row.ciphertext});const payload=JSON.parse(decoder.decode(raw));let attachment=null;if(payload.type==='image')attachment=await loadStoredImage(c.id,payload,row.messageId);if(generation!==sessionGeneration||ownerId!==user?.id){if(attachment?.url)URL.revokeObjectURL(attachment.url);return}appendMessage(c.id,payload.text||'',!!row.mine,row.at,payload.reply?(row.mine?payload.reply:{...payload.reply,mine:!payload.reply.mine}):null,attachment,row.messageId,false)}catch(e){if(generation===sessionGeneration)console.warn('[AELTRIX] Local message could not be decrypted',e)}}if(generation===sessionGeneration&&activeChatId===c.id)renderMessages(c)}catch(e){if(generation===sessionGeneration){console.warn('[AELTRIX] Local history load failed',e);toast('تعذر تحميل المحادثات المحلية. قد تكون بيانات المتصفح حُذفت.',true)}}}
async function saveIncomingText(peerId,payload,messageId,at){try{await persistPayload(peerId,payload,messageId,at,false)}catch(e){console.warn('[AELTRIX] Incoming message local save failed',e);toast('وصلت الرسالة، لكن تعذّر حفظها محليًا.',true)}}
async function wireConnection(conn,isInitiator){
 conn._aeltrixKey=null;conn._aeltrixReady=false;conn._aeltrixDataQueue=Promise.resolve();
 conn._aeltrixKeyPair=await crypto.subtle.generateKey({name:'ECDH',namedCurve:'P-256'},true,['deriveBits']);
 const meta=conn.metadata||{},localId=user?.id,expectedRemoteId=isInitiator?meta.recipientUserId:meta.initiatorUserId,expectedLocalId=isInitiator?meta.initiatorUserId:meta.recipientUserId;const accepted=!isInitiator?acceptedInvites.get(meta.inviteId):null;if(meta.protocol!==2||!meta.inviteId||!localId||expectedLocalId!==localId||!expectedRemoteId||expectedRemoteId===localId||(!isInitiator&&(!accepted||accepted.expiresAt<Date.now()||accepted.remoteId!==expectedRemoteId))){toast('هوية اتصال أو دعوة غير صالحة. أعد إرسال الدعوة.',true);conn.close();return}if(!isInitiator)acceptedInvites.delete(meta.inviteId);const remoteId=expectedRemoteId,remoteName=(isInitiator?meta.recipientName:meta.initiatorName)||'صديق AELTRIX',chatId=remoteId;
 conn.on('open',async()=>{try{createChatRecord(chatId,remoteName,conn);if(!chats.get(chatId)?.conn)chats.get(chatId).conn=conn;conn.send(await makeSignedHello(conn,meta,chatId));toast('اتصلنا! نتحقق من هوية الطرف الآخر…')}catch(e){console.error(e);conn.close();toast('تعذر بدء المصافحة الآمنة.',true)}});
 conn.on('data',data=>{conn._aeltrixDataQueue=conn._aeltrixDataQueue.then(()=>processIncomingData(data)).catch(e=>{console.warn('[AELTRIX] incoming data failed',e);if(!conn._aeltrixReady)conn.close();toast(e.message||'تعذر استلام الرسالة أو الصورة كاملة.',true)})});
 async function processIncomingData(data){
  if(data?.kind==='hello'&&data.key&&data.signature){await verifySignedHello(conn,data,chatId,meta);return}
  if(!conn._aeltrixKey)throw new Error('مفتاح التشفير لم يجهز بعد');
  if(data?.kind==='message'&&data.iv&&data.cipher){const raw=await decryptPacket(conn._aeltrixKey,data),decoded=decoder.decode(raw);let payload;try{payload=JSON.parse(decoded)}catch{payload={type:'text',text:decoded}};if(payload.type==='text'){const at=data.at||Date.now(),id=data.messageId||crypto.randomUUID();await saveIncomingText(chatId,payload,id,at);appendMessage(chatId,payload.text||'',false,at,payload.reply?{...payload.reply,mine:!payload.reply.mine}:null,null,id,false)}return}
  if(data?.kind==='image-ack'&&data.transferId){const pending=outgoingTransfers.get(data.transferId);if(!pending)return;const result=JSON.parse(decoder.decode(await decryptPacket(conn._aeltrixKey,data)));clearTimeout(pending.timer);outgoingTransfers.delete(data.transferId);result.ok?pending.resolve(result):pending.reject(new Error(result.error||'لم يؤكد الطرف الآخر حفظ الصورة'));return}
  if(data?.kind==='image-cancel'&&data.transferId){const transfer=incomingTransfers.get(data.transferId);if(transfer?.conn===conn){clearTimeout(transfer.timer);incomingTransfers.delete(data.transferId)}return}
  if(data?.kind==='image-start'&&data.transferId&&data.meta){if(incomingTransfers.has(data.transferId)||incomingTransfers.size>=2)throw new Error('عدد عمليات نقل الصور غير مسموح');const raw=await decryptPacket(conn._aeltrixKey,data.meta),imageMeta=JSON.parse(decoder.decode(raw)),reserved=[...incomingTransfers.values()].reduce((sum,t)=>sum+t.meta.size,0);if(!Number.isFinite(imageMeta.size)||imageMeta.size<1||imageMeta.size>=20*1024*1024||reserved+imageMeta.size>20*1024*1024)throw new Error('حجم الصورة أو الذاكرة المحجوزة غير مسموح');if(!['image/png','image/jpeg','image/webp','image/gif'].includes(imageMeta.type)||typeof imageMeta.name!=='string'||!Number.isInteger(data.total)||data.total!==Math.ceil(imageMeta.size/(12*1024))||typeof data.messageId!=='string')throw new Error('بيانات الصورة غير صالحة');const transfer={meta:imageMeta,chunks:new Array(data.total),received:0,bytes:0,at:data.at||Date.now(),messageId:data.messageId,conn,timer:null};transfer.timer=setTimeout(()=>{incomingTransfers.delete(data.transferId);toast('انتهت مهلة استلام الصورة غير المكتملة.',true)},90000);incomingTransfers.set(data.transferId,transfer);return}
  if(data?.kind==='image-chunk'&&data.transferId){const transfer=incomingTransfers.get(data.transferId);if(!transfer||transfer.conn!==conn||!Number.isInteger(data.index)||data.index<0||data.index>=transfer.chunks.length||transfer.chunks[data.index])return;const chunk=await decryptPacket(conn._aeltrixKey,data);if(chunk.byteLength>12*1024||transfer.bytes+chunk.byteLength>transfer.meta.size)throw new Error('حجم أجزاء الصورة تجاوز الحد المعلن');transfer.chunks[data.index]=chunk;transfer.bytes+=chunk.byteLength;transfer.received++;return}
  if(data?.kind==='image-end'&&data.transferId){const transfer=incomingTransfers.get(data.transferId);if(!transfer||transfer.conn!==conn)return;clearTimeout(transfer.timer);incomingTransfers.delete(data.transferId);try{if(transfer.received!==transfer.chunks.length||transfer.chunks.some(x=>!x)||transfer.bytes!==transfer.meta.size)throw new Error('اكتمل وصول أجزاء غير كافية من الصورة');const blob=new Blob(transfer.chunks,{type:transfer.meta.type||'image/png'}),chat=chats.get(chatId)||createChatRecord(chatId,remoteName,conn),file=new File([blob],transfer.meta.name||'image',{type:transfer.meta.type||'image/png'});await persistEncryptedImage(chat,file,transfer.messageId,transfer.at,false);const url=URL.createObjectURL(blob);appendMessage(chatId,'',false,transfer.at,null,{type:'image',url,name:transfer.meta.name,size:transfer.meta.size},transfer.messageId,false);const ack=await encryptPacket(conn._aeltrixKey,encoder.encode(JSON.stringify({ok:true})));conn.send({kind:'image-ack',transferId:data.transferId,...ack})}catch(error){const ack=await encryptPacket(conn._aeltrixKey,encoder.encode(JSON.stringify({ok:false,error:'تعذر حفظ الصورة على جهاز المستلم'})));conn.send({kind:'image-ack',transferId:data.transferId,...ack});throw error}return}
 }
 conn.on('close',()=>{clearTransfersForConnection(conn);updateChatStatus(chatId,false);toast('انقطع اتصال المحادثة.',true)});conn.on('error',e=>{console.warn(e);clearTransfersForConnection(conn);updateChatStatus(chatId,false)})
}
function createChatRecord(id,name,conn){let c;if(!chats.has(id)){c={id,name,conn,connected:false,messages:[]};chats.set(id,c)}else{c=chats.get(id);c.name=name||c.name;c.conn=conn||c.conn}if(user&&id&&id!==user.id)saveLocalContact(id,c.name).catch(e=>console.warn('[AELTRIX] contact save failed',e));renderChatList();return c}
function updateChatStatus(id,connected){const c=chats.get(id);if(c){c.connected=connected;renderChatList();if(activeChatId===id){const status=$('activeChatStatus');if(status)status.textContent=connected?'متصل ومشفّر':'غير متصل'}}}
async function sendChatMessage(){const c=chats.get(activeChatId),box=$('messageInput'),ownerId=user?.id,generation=sessionGeneration;if(!c||!ownerId||!c.conn?.open||!c.conn._aeltrixKey){toast('انتظر حتى يصبح الاتصال مشفّرًا.',true);return}const value=box.value.trim();if(!value)return;try{const at=Date.now(),messageId=crypto.randomUUID(),payload={type:'text',text:value,reply:replyDraft};await persistPayload(c.id,payload,messageId,at);if(generation!==sessionGeneration||ownerId!==user?.id||!c.conn?.open)throw new Error('تغيرت الجلسة أو انقطع الاتصال');const packet=await encryptPacket(c.conn._aeltrixKey,encoder.encode(JSON.stringify(payload)));if(generation!==sessionGeneration||ownerId!==user?.id||!c.conn?.open)throw new Error('تغيرت الجلسة أو انقطع الاتصال');c.conn.send({kind:'message',...packet,at,messageId});appendMessage(c.id,value,true,at,replyDraft,null,messageId);box.value='';clearReplyDraft()}catch(e){console.error(e);toast('لم نتمكن من حفظ أو إرسال الرسالة. '+(e.message||''),true)}}
function appendMessage(id,text,mine,at,reply=null,attachment=null,messageId=null,save=true,delivery=''){const c=chats.get(id);if(!c)return;const finalId=messageId||crypto.randomUUID();if(c.messages.some(m=>m.id===finalId))return;const message={id:finalId,text,mine,at,reply,attachment,delivery};c.messages.push(message);if(save&&user){const payload=attachment?.type==='image'?{type:'image',name:attachment.name||'صورة',size:attachment.size||0,mime:attachment.mime||'image/png',localMediaKey:localKey(id,finalId)}:{type:'text',text,reply};persistPayload(id,payload,finalId,at,mine).catch(e=>console.warn('[AELTRIX] local save failed',e))}if(activeChatId===id)renderMessages(c);renderChatList()}
function quoteText(m){if(m.attachment?.type==='image')return m.attachment.name?.toLowerCase().includes('sticker')?'✨ ملصق':'📷 صورة';return (m.text||'').slice(0,100)}
function renderMessages(c){const list=$('chatMessages');if(!list)return;list.innerHTML=c.messages.map(m=>{const reply=m.reply?`<div class="reply-quote"><b>رد على ${m.reply.mine?'رسالتك':'رسالة الصديق'}</b><span>${escapeHtml(m.reply.preview||'رسالة')}</span></div>`:'';const isSticker=m.attachment?.type==='image'&&m.attachment.name?.toLowerCase().startsWith('sticker-');const body=m.attachment?.type==='image'?`<a href="${m.attachment.url}" target="_blank" rel="noopener"><img class="chat-image ${isSticker?'sticker-message':''}" src="${m.attachment.url}" alt="${escapeHtml(m.attachment.name||'صورة')}" loading="lazy"></a>${isSticker?'':`<small class="image-caption">${escapeHtml(m.attachment.name||'صورة')} · ${(m.attachment.size/1024/1024).toFixed(1)} MB</small>`}`:`<div class="bubble">${escapeHtml(m.text)}</div>`;return `<div class="message ${m.mine?'mine':'theirs'}" data-message="${escapeHtml(m.id)}">${reply}${body}<div class="message-meta"><time>${new Date(m.at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</time>${m.delivery?`<span class="delivery-state">${escapeHtml(m.delivery)}</span>`:''}<button class="reply-btn" data-reply="${escapeHtml(m.id)}" title="الرد على الرسالة">↩ رد</button></div></div>`}).join('');list.querySelectorAll('[data-reply]').forEach(b=>b.onclick=()=>{const m=c.messages.find(x=>x.id===b.dataset.reply);if(m){replyDraft={id:m.id,preview:quoteText(m),mine:m.mine};showReplyDraft();$('messageInput')?.focus()}});list.scrollTop=list.scrollHeight}
function showReplyDraft(){const el=$('replyDraft');if(!el)return;if(!replyDraft){el.classList.add('hidden');el.innerHTML='';return}el.classList.remove('hidden');el.innerHTML=`<div><b>الرد على ${replyDraft.mine?'رسالتك':'رسالة الصديق'}</b><span>${escapeHtml(replyDraft.preview)}</span></div><button type="button" id="cancelReply" aria-label="إلغاء الرد">×</button>`;$('cancelReply').onclick=clearReplyDraft}
function clearReplyDraft(){replyDraft=null;showReplyDraft()}
async function waitForDataChannelSpace(conn){const dc=conn.dataChannel;if(!dc)throw new Error('قناة البيانات غير جاهزة');const deadline=Date.now()+30000;while(dc.readyState==='open'&&dc.bufferedAmount>192*1024&&Date.now()<deadline)await new Promise(r=>setTimeout(r,25));if(dc.readyState!=='open')throw new Error('قناة الاتصال انقطعت');if(Date.now()>=deadline)throw new Error('توقفت قناة الاتصال عن استقبال البيانات')}
async function transmitImageAttempt(c,file,messageId,at,attempt,status){const transferId=`${messageId}:${attempt}`,chunkSize=12*1024,total=Math.ceil(file.size/chunkSize),meta=await encryptPacket(c.conn._aeltrixKey,encoder.encode(JSON.stringify({name:file.name||'image',type:file.type,size:file.size})));let resolveAck,rejectAck;const ack=new Promise((resolve,reject)=>{resolveAck=resolve;rejectAck=reject});const timer=setTimeout(()=>{outgoingTransfers.delete(transferId);const error=new Error('تأخر تأكيد الاستلام');error.code='ACK_TIMEOUT';rejectAck(error)},45000);outgoingTransfers.set(transferId,{resolve:resolveAck,reject:rejectAck,timer,conn:c.conn});try{await waitForDataChannelSpace(c.conn);c.conn.send({kind:'image-start',transferId,messageId,total,meta,at});for(let i=0;i<total;i++){await waitForDataChannelSpace(c.conn);const bytes=new Uint8Array(await file.slice(i*chunkSize,Math.min(file.size,(i+1)*chunkSize)).arrayBuffer()),packet=await encryptPacket(c.conn._aeltrixKey,bytes);c.conn.send({kind:'image-chunk',transferId,index:i,...packet});if(status)status.textContent=`جارٍ الإرسال… ${Math.round((i+1)/total*100)}%`}await waitForDataChannelSpace(c.conn);c.conn.send({kind:'image-end',transferId});await ack;return transferId}catch(error){const pending=outgoingTransfers.get(transferId);if(pending){clearTimeout(pending.timer);outgoingTransfers.delete(transferId)}if(c.conn.open)c.conn.send({kind:'image-cancel',transferId});throw error}}
async function sendImage(file){const c=chats.get(activeChatId);if(!c||!c.conn?.open||!c.conn._aeltrixKey){toast('انتظر حتى يصبح الاتصال مشفّرًا.',true);return}if(!file||!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type)){toast('اختر PNG أو JPG أو WEBP أو GIF صالحًا.',true);return}if(file.size<1||file.size>=20*1024*1024){toast('حجم الصورة لازم يكون أكبر من صفر وأقل من 20MB.',true);return}const picker=$('imageInput'),sendBtn=$('sendMessage'),status=$('transferStatus');if(sendBtn)sendBtn.disabled=true;if(status){status.textContent='نجهّز الصورة…';status.classList.remove('hidden')}let messageId=null,at=Date.now(),localSaved=false;try{messageId=crypto.randomUUID();await persistEncryptedImage(c,file,messageId,at);localSaved=true;let delivered=false,lastError=null;for(let attempt=1;attempt<=2&&!delivered;attempt++){try{await transmitImageAttempt(c,file,messageId,at,attempt,status);delivered=true}catch(error){lastError=error;if(error.code!=='ACK_TIMEOUT'||attempt===2||!c.conn.open)throw error;toast('لم يصل تأكيد الاستلام؛ نعيد محاولة النقل مرة واحدة…',true)}}if(!delivered)throw lastError||new Error('تعذر إرسال الصورة');const url=URL.createObjectURL(file),isSticker=file.name.toLowerCase().startsWith('sticker-');appendMessage(c.id,'',true,at,null,{type:'image',url,name:file.name,size:file.size},messageId,false,'مستلمة');toast(isSticker?'تم استلام الملصق بنجاح ✨':'أكد الطرف الآخر استلام الصورة.')}catch(e){console.error(e);if(localSaved&&messageId&&!c.messages.some(m=>m.id===messageId)){const url=URL.createObjectURL(file);appendMessage(c.id,'',true,at,null,{type:'image',url,name:file.name,size:file.size},messageId,false,'غير مُسلّمة')}toast('فشل تأكيد إرسال الصورة: '+(e.message||'تحقق من الاتصال ثم أعد المحاولة.'),true)}finally{if(sendBtn)sendBtn.disabled=false;if(picker)picker.value='';if(status){status.textContent='';status.classList.add('hidden')}}}
async function openChat(id){const c=chats.get(id);if(!c)return;activeChatId=id;replyDraft=null;$('chatPanel').innerHTML=`<div class="chat-head"><div class="avatar">${escapeHtml(initials(c.name))}</div><div class="head-info"><b>${escapeHtml(c.name)}</b><small id="activeChatStatus">${c.connected?'متصل ومشفّر':'جارٍ الاتصال…'}</small></div><span class="secure-label">⌑ E2EE</span></div><div id="chatMessages" class="chat-messages"></div><div class="reply-draft hidden" id="replyDraft"></div><div class="chat-compose-wrap"><div class="chat-compose"><button class="compose-icon" id="chooseImage" type="button" title="إرسال صورة" aria-label="إرسال صورة">＋</button><input id="imageInput" type="file" accept="image/*" hidden><button class="compose-icon sticker-compose" id="openStickers" type="button" title="ملصقاتي" aria-label="فتح الملصقات">☺</button><textarea id="messageInput" rows="1" aria-label="اكتب رسالة" placeholder="اكتب رسالة…"></textarea><button class="compose-send" id="sendMessage" type="button" aria-label="إرسال الرسالة" title="إرسال">➤</button></div><small id="transferStatus" class="transfer-status hidden" aria-live="polite"></small></div>`;renderMessages(c);const box=$('messageInput');$('sendMessage').onclick=sendChatMessage;box.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendChatMessage()} });box.addEventListener('input',()=>{box.style.height='auto';box.style.height=Math.min(box.scrollHeight,120)+'px'});$('chooseImage').onclick=()=>$('imageInput').click();$('openStickers').onclick=()=>openStickerStudio();$('imageInput').onchange=e=>{const f=e.target.files?.[0];if(f)sendImage(f)};renderChatList();await loadChatHistory(c)}
function renderChatList(){const el=$('chatList');if(!chats.size){el.innerHTML='<div class="empty-state compact">لم تبدأ أي محادثة بعد.</div>';return}el.innerHTML=[...chats.values()].map(c=>`<button class="chat-list-item ${c.id===activeChatId?'active':''}" data-chat="${escapeHtml(c.id)}"><span class="avatar">${escapeHtml(initials(c.name))}</span><span class="invite-info"><b>${escapeHtml(c.name)}</b><small>${c.connected?'● متصل ومشفّر':'○ غير متصل'}</small></span></button>`).join('');el.querySelectorAll('[data-chat]').forEach(b=>b.onclick=()=>openChat(b.dataset.chat))}
function renderInvites(){const el=$('incomingInvites');$('pendingCount').textContent=incomingInvites.size;$('inviteBadge').textContent=incomingInvites.size;$('inviteBadge').classList.toggle('hidden',incomingInvites.size===0);if(!incomingInvites.size){el.innerHTML='<div class="empty-state compact">لا توجد دعوات الآن.</div>';return}el.innerHTML=[...incomingInvites.values()].map(i=>`<div class="invite-item"><span class="avatar">${escapeHtml(initials(i.from_name||i.from_username))}</span><span class="invite-info"><b>@${escapeHtml(i.from_username)}</b><small>دعوة محادثة خاصة</small></span><span class="invite-actions"><button data-accept="${escapeHtml(i.invite_id)}">قبول</button><button class="decline" data-decline="${escapeHtml(i.invite_id)}">رفض</button></span></div>`).join('');el.querySelectorAll('[data-accept]').forEach(b=>b.onclick=()=>replyInvite(incomingInvites.get(b.dataset.accept),true));el.querySelectorAll('[data-decline]').forEach(b=>b.onclick=()=>replyInvite(incomingInvites.get(b.dataset.decline),false))}

$('peopleSearch').addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>searchPeople($('peopleSearch').value.trim()),250)});$('clearSearch').onclick=()=>{$('peopleSearch').value='';searchPeople('')};
async function searchPeople(query){if(!supabase||!myProfile||!user)return;const generation=sessionGeneration,ownerId=user.id,el=$('peopleResults');if(!query){renderPeopleFromOnline();return}if(query.length<2){el.innerHTML='<div class="empty-state">اكتب حرفين على الأقل للبحث.</div>';return}const {data,error}=await supabase.from('profiles').select('id,username,display_name,bio').ilike('username',query.replace(/[%_]/g,'')+'%').neq('id',ownerId).limit(30);if(generation!==sessionGeneration||ownerId!==user?.id)return;if(error){el.innerHTML='<div class="empty-state">تعذر البحث. تأكد من إعداد جدول profiles وRLS.</div>';return}renderPeople(data||[],true)}
function renderPeopleFromOnline(){const query=$('peopleSearch')?.value.trim();if(query){return}const data=[...onlineUsers.values()].map(p=>({...p,id:p.user_id,username:p.username,display_name:p.display_name,peer_id:p.peer_id,isOnline:true}));renderPeople(data,false)}
function renderPeople(list,fromSearch){const el=$('peopleResults');if(!el)return;if(!list.length){el.innerHTML=`<div class="empty-state">${fromSearch?'ما لقينا مستخدم بهذا الاسم.':'لا يوجد أصحاب متصلون حاليًا. جرّب البحث عن اسم مستخدم.'}</div>`;return}el.innerHTML=list.map(p=>{const online=fromSearch?onlineUsers.has(p.id):true;const live=onlineUsers.get(p.id);const person={...p,peer_id:live?.peer_id||p.peer_id};return `<article class="person-card"><span class="avatar">${escapeHtml(initials(p.display_name||p.username))}</span><div class="person-info"><b>${escapeHtml(p.display_name||p.username)}</b><small>@${escapeHtml(p.username)}${p.bio?' · '+escapeHtml(p.bio):''}</small><span class="online-label"><span class="pulse-dot" style="background:${online?'var(--green)':'#65756a'}"></span>${online?'متصل الآن':'غير متصل'}</span></div>${online&&person.peer_id?`<button class="primary-btn" data-invite="${escapeHtml(p.id)}">دعوة ↗</button>`:`<button class="outline-btn" disabled>${online?'يجهز الاتصال':'غير متصل'}</button>`}</article>`}).join('');el.querySelectorAll('[data-invite]').forEach(b=>b.onclick=()=>{const p=list.find(x=>x.id===b.dataset.invite);const live=onlineUsers.get(p.id);sendInvite({...p,...live,id:p.id})})}
async function loadOnlinePreview(){const el=$('onlinePreview');if(!el||!myProfile)return;const list=[...onlineUsers.values()];if(!list.length){el.innerHTML='<div class="empty-state compact">لا يوجد أحد متصل غيرك حاليًا. شارك رابط الموقع مع أصحابك.</div>';return}el.innerHTML=list.slice(0,8).map(p=>`<div class="person-chip"><span class="avatar">${escapeHtml(initials(p.display_name||p.username))}</span><b>@${escapeHtml(p.username)}</b><small><span class="pulse-dot"></span>متصل الآن</small><button data-preview-invite="${escapeHtml(p.user_id)}">دعوة للمحادثة</button></div>`).join('');el.querySelectorAll('[data-preview-invite]').forEach(b=>b.onclick=()=>{const p=onlineUsers.get(b.dataset.previewInvite);if(p)sendInvite({...p,id:p.user_id})})}

let stickerSourceFile=null,stickerPreviewBlob=null,stickerPreviewName='ملصق',stickerObjectUrls=[],stickerRenderToken=0;
function openStickerStudio(){if(!$('stickerModal'))return;$('stickerModal').classList.remove('hidden');renderStickerLibrary();if(stickerSourceFile)drawStickerPreview()}
function closeStickerStudio(){$('stickerModal')?.classList.add('hidden')}
$('closeStickerStudio')?.addEventListener('click',closeStickerStudio);document.querySelectorAll('[data-sticker-close]').forEach(x=>x.addEventListener('click',closeStickerStudio));
function drawStickerPreview(){const canvas=$('stickerCanvas');if(!canvas)return;const token=++stickerRenderToken,ctx=canvas.getContext('2d');ctx.clearRect(0,0,512,512);const bg=$('stickerBackground')?.value||'transparent';if(bg!=='transparent'){ctx.fillStyle=bg;ctx.fillRect(0,0,512,512)}stickerPreviewBlob=null;$('saveSticker').disabled=true;if(!stickerSourceFile)return;if(!['image/png','image/jpeg','image/webp','image/gif'].includes(stickerSourceFile.type)||stickerSourceFile.size<1||stickerSourceFile.size>=20*1024*1024){toast('اختر PNG أو JPG أو WEBP أو GIF أقل من 20MB.',true);return}createImageBitmap(stickerSourceFile).then(bitmap=>{if(token!==stickerRenderToken){bitmap.close();return}if(bitmap.width*bitmap.height>16000000){bitmap.close();throw new Error('أبعاد الصورة أكبر من الحد المسموح')}const scale=Math.min(410/bitmap.width,410/bitmap.height)*(Number($('stickerScale')?.value||100)/100),w=bitmap.width*scale,h=bitmap.height*scale,x=(512-w)/2,y=(512-h)/2;ctx.save();ctx.shadowColor='rgba(35,20,60,.22)';ctx.shadowBlur=12;ctx.drawImage(bitmap,x,y,w,h);ctx.restore();bitmap.close();const caption=$('stickerCaption').value.trim();if(caption){const fontSize=Number($('stickerTextSize')?.value||42);ctx.font=`900 ${fontSize}px system-ui, sans-serif`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.lineJoin='round';ctx.strokeStyle='rgba(20,18,35,.92)';ctx.lineWidth=Math.max(5,fontSize*.18);ctx.strokeText(caption,256,456,470);ctx.fillStyle='#fff';ctx.fillText(caption,256,456,470)}canvas.toBlob(blob=>{if(token!==stickerRenderToken)return;if(blob){stickerPreviewBlob=blob;$('saveSticker').disabled=false}else{toast('تعذر إنشاء ملف معاينة الملصق.',true)}},'image/png')}).catch(e=>{console.warn(e);toast(e.message||'تعذر تجهيز معاينة الملصق.',true)})}
$('stickerSource')?.addEventListener('change',e=>{stickerSourceFile=e.target.files?.[0]||null;stickerPreviewName=(stickerSourceFile?.name||'ملصق').replace(/\.[^.]+$/,'').slice(0,30)||'ملصق';if($('stickerName'))$('stickerName').value=stickerPreviewName;drawStickerPreview()});['stickerCaption','stickerBackground','stickerScale','stickerTextSize'].forEach(id=>$(id)?.addEventListener('input',drawStickerPreview));
$('saveSticker')?.addEventListener('click',async()=>{const ownerId=user?.id,generation=sessionGeneration,blob=stickerPreviewBlob;if(!ownerId||!blob)return;try{const id=crypto.randomUUID(),name=(($('stickerName')?.value||'').trim()||stickerPreviewName||'ملصق').slice(0,30);await localStore('stickers','readwrite',store=>store.put({key:`${ownerId}:${id}`,ownerId,id,name,blob,createdAt:Date.now()}));if(generation===sessionGeneration&&ownerId===user?.id){toast('انحفظ الملصق في مكتبتك ✨');renderStickerLibrary()}}catch(e){if(generation===sessionGeneration){console.error(e);toast('تعذر حفظ الملصق. قد تكون مساحة المتصفح ممتلئة.',true)}}});
async function renderStickerLibrary(){const el=$('stickerLibrary');if(!el||!user)return;for(const url of stickerObjectUrls)URL.revokeObjectURL(url);stickerObjectUrls=[];try{const rows=(await localGetAll('stickers')).filter(s=>s.ownerId===user.id).sort((a,b)=>b.createdAt-a.createdAt);if(!rows.length){el.innerHTML='<div class="empty-state compact">مكتبتك فاضية حاليًا — اصنع أول ملصق من الأعلى.</div>';return}el.innerHTML=rows.map(s=>{const imageUrl=URL.createObjectURL(s.blob);stickerObjectUrls.push(imageUrl);return `<div class="sticker-tile"><button class="sticker-use" type="button" data-use-sticker="${escapeHtml(s.id)}" aria-label="إرسال ${escapeHtml(s.name)}"><img alt="" src="${imageUrl}"><small>${escapeHtml(s.name)}</small><span>إرسال ↗</span></button><button class="sticker-delete" type="button" data-delete-sticker="${escapeHtml(s.id)}" aria-label="حذف الملصق">×</button></div>`}).join('');el.querySelectorAll('[data-use-sticker]').forEach(b=>b.addEventListener('click',async()=>{const row=rows.find(s=>s.id===b.dataset.useSticker);if(!row)return;if(!activeChatId){toast('افتح محادثة أولًا ثم اختر الملصق.',true);return}const safeName=row.name.replace(/[^\w\u0600-\u06FF-]/g,'_');const file=new File([row.blob],`sticker-${safeName}.png`,{type:'image/png'});closeStickerStudio();await sendImage(file)}));el.querySelectorAll('[data-delete-sticker]').forEach(b=>b.addEventListener('click',async ev=>{ev.stopPropagation();const ownerId=user?.id,generation=sessionGeneration,id=b.dataset.deleteSticker;if(!ownerId)return;await localStore('stickers','readwrite',store=>store.delete(`${ownerId}:${id}`));if(generation===sessionGeneration&&ownerId===user?.id)renderStickerLibrary()}))}catch(e){console.warn('[AELTRIX] sticker library load failed',e);el.innerHTML='<div class="empty-state compact">تعذر فتح مكتبة الملصقات.</div>'}}
function cleanup(){for(const [id,t] of incomingTransfers){clearTimeout(t.timer);incomingTransfers.delete(id)}for(const [id,t] of outgoingTransfers){clearTimeout(t.timer);outgoingTransfers.delete(id);t.reject?.(new Error('تم تسجيل الخروج'))}try{peer?.destroy()}catch{}try{if(presenceChannel)supabase?.removeChannel(presenceChannel)}catch{}try{if(inviteChannel)supabase?.removeChannel(inviteChannel)}catch{}peer=null;presenceChannel=null;inviteChannel=null;peerConnections.clear();for(const c of chats.values())for(const m of c.messages)if(m.attachment?.url?.startsWith('blob:'))URL.revokeObjectURL(m.attachment.url);for(const url of stickerObjectUrls||[])URL.revokeObjectURL(url);if(typeof stickerObjectUrls!=='undefined')stickerObjectUrls=[];chats.clear();incomingInvites.clear();outgoingInvites.clear();acceptedInvites.clear();onlineUsers.clear();persistentKeys.clear();identityPrivateKey=null;identityPublicJwk=null;signingPrivateKey=null;signingPublicJwk=null;pendingModalInvite=null;stickerSourceFile=null;stickerPreviewBlob=null;stickerRenderToken++;$('stickerModal')?.classList.add('hidden')}
if(configReady()){if(initSupabase()){supabase.auth.onAuthStateChange((event)=>{if(event==='SIGNED_OUT'){sessionGeneration++;cleanup();user=null;myProfile=null;authView.classList.remove('hidden');appView.classList.add('hidden')}});supabase.auth.getSession().then(({data:{session}})=>{if(session)enterApp().catch(e=>{console.error(e);toast(friendlyError(e),true)})})}}else{authMsg('إعداد Supabase ناقص: تأكد من رفع config.js بجانب index.html وأنه يحتوي رابط المشروع والمفتاح العام الصحيحين.',true)}
